const r = $input.item.json;
const data = r.data || r;
const ts = new Date().toLocaleString('en-US', {timeZone: 'America/Denver', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'});

const stories = data.stories || data.articles || data.items || [];
const travelTech = data.travel_tech || [];
const aiNews = data.ai_news || data.ai_stories || [];

let body = '';
if (stories.length) {
  const top = stories.slice(0,5).map(s => {
    const source = s.source ? ` (${s.source})` : '';
    return `• ${s.title || s.headline}${source}`;
  });
  body = top.join('\n');
} else if (data.summary || data.result) {
  body = data.summary || data.result;
} else {
  body = JSON.stringify(data).slice(0, 600);
}

let travelBlock = '';
if (travelTech.length) {
  travelBlock = '\n\n*Travel Tech:*\n' + travelTech.slice(0,3).map(t => `• ${t.title || t}`).join('\n');
}

let aiBlock = '';
if (aiNews.length) {
  aiBlock = '\n\n*AI / Automation:*\n' + aiNews.slice(0,3).map(a => `• ${a.title || a}`).join('\n');
}

const message = `*D2M Tech Monitor — ${ts}*\n\n${body}${travelBlock}${aiBlock}`;
return [{ json: { message } }];
